import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.Cvf4Fkn6.js";const p=JSON.parse('{"title":"使用指南总览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1794574960000}'),i={name:"guide/index.md"};function h(o,t,l,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="使用指南总览" tabindex="-1">使用指南总览 <a class="header-anchor" href="#使用指南总览" aria-label="Permalink to &quot;使用指南总览&quot;">​</a></h1><p>WTidy 是原生重制的 macOS 窗口分屏工具（Swift + AppKit），致敬 Window Tidy（Light Pillar, 2011–2017）。它把「拖动窗口 → 浮现布局图标条 → 图标内瞄准 → 松手吸附」做为核心交互，配合布局自定义、每区域快捷键与菜单栏应用布局，覆盖日常所有分屏场景。</p><h2 id="功能矩阵" tabindex="-1">功能矩阵 <a class="header-anchor" href="#功能矩阵" aria-label="Permalink to &quot;功能矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th><th>文档</th></tr></thead><tbody><tr><td>拖拽分屏</td><td>拖动窗口浮现布局图标条，图标内投影瞄准 + 整屏落点预览</td><td><a href="./drag-snap.html">拖拽分屏与布局条</a></td></tr><tr><td>布局自定义</td><td>网格 + 区域模型编辑器，内置 8 种布局，按显示器设作用域</td><td><a href="./layouts.html">布局自定义</a></td></tr><tr><td>全局快捷键</td><td>内置布局自带 ⌥⌘ 加一键的默认快捷键，每区域可改录，冲突自动拦截</td><td><a href="./hotkeys.html">快捷键</a></td></tr><tr><td>设置页</td><td>行为 / 定位 / 图标条主题 / 开机自启</td><td><a href="./settings.html">设置页详解</a></td></tr><tr><td>安装与授权</td><td>下载安装、辅助功能授权、从源码构建</td><td><a href="./getting-started.html">快速开始</a></td></tr><tr><td>故障排查</td><td>图标条不出现、授权失效、与系统分屏共存等</td><td><a href="./faq.html">常见问题</a></td></tr></tbody></table><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>macOS 13.0 及以上</td></tr><tr><td>机型</td><td>Apple Silicon（arm64 原生构建，不依赖 Rosetta 2；Intel 机器可自行源码构建）</td></tr><tr><td>辅助功能权限</td><td>必需（首次启动引导授权）</td></tr><tr><td>源码构建</td><td>Command Line Tools 即可，无需 Xcode</td></tr></tbody></table><h2 id="设计与可靠性" tabindex="-1">设计与可靠性 <a class="header-anchor" href="#设计与可靠性" aria-label="Permalink to &quot;设计与可靠性&quot;">​</a></h2><p>WTidy 与 2017 年的原版有三个核心差异：登录自启改用 SMAppService（BTM 原生），拖拽监听由看门狗守护（事件驱动重挂 + 心跳 + 周期重建），arm64 原生不再依赖 Rosetta 2。详见<a href="./settings.html#可靠性">设置页详解 · 可靠性</a>。</p><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><p>问题请到 GitHub <a href="https://github.com/crazy-airhead/WTidy/issues" target="_blank" rel="noreferrer">Issues</a> 反馈，附上 <code>~/Library/Logs/WTidy.log</code> 尾部内容可以更快定位。</p>',10)])])}const b=a(i,[["render",h]]);export{p as __pageData,b as default};
